#!/usr/bin/env node
// in-21 — bundles in-20's generated JSON-Schema catalog (the five committed
// artifacts under `contracts/json/integrations/**` that `scripts/contract-schema
// -export.mjs` emits from the orchestrator's Zod contracts) into a single
// dashboard-owned TS module the Integration Control Center serves as a
// downloadable artifact.
//
// Source of truth: contracts/json/integrations/*.json  (the in-20 surface: the
//   drift-gated, language-neutral JSON-Schema files `scripts/contract-schema-
//   export.mjs` regenerates from `routes/integrations/contract.ts`).
// Generated output: services/dashboard/src/api/integrationReadSchemaCatalog.gen.ts
//   (a typed `integrationReadSchemaCatalog` const — one entry per response).
//
// Acts as both a codegen step (no flags) and a drift check (--check), mirroring
// scripts/gen-dashboard-types.mjs and scripts/answerer-schema-export.mjs so
// `just fast-check` fails if the bundled TS diverges from the committed JSON.
//
// Usage:
//   node scripts/gen-integration-schema-bundle.mjs           # write if drifted
//   node scripts/gen-integration-schema-bundle.mjs --check    # exit 1 on drift

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { resolve } from "node:path";
import { argv, exit } from "node:process";

const repoRoot = resolve(import.meta.dirname, "..");
const schemaDir = resolve(repoRoot, "contracts/json/integrations");
const outFile = resolve(repoRoot, "services/dashboard/src/api/integrationReadSchemaCatalog.gen.ts");
const outFileRel = "services/dashboard/src/api/integrationReadSchemaCatalog.gen.ts";

// The five in-20 read-surface response schemas. The integrations tree also
// holds `IntegrationsManifestV1.json` (in-8's `.tanren/integrations.yml`
// manifest schema, not part of the read HTTP surface) — exclude it so the
// download mirrors exactly the surface the Control Center documents.
const READ_SURFACE_FILES = new Set([
  "IntegrationLifecycleInventoryResponse.json",
  "IntegrationRequirementsResponse.json",
  "CapabilityNodesResponse.json",
  "IntegrationBindingsResponse.json",
  "DeliveryDagStatusResponse.json",
]);

function readEntry(file) {
  const raw = readFileSync(resolve(schemaDir, file), "utf8");
  const parsed = JSON.parse(raw);
  const schemaId = parsed["x-tanren-schema-id"];
  if (typeof schemaId !== "string" || schemaId.length === 0) {
    throw new Error(`${file} is missing x-tanren-schema-id`);
  }
  return { file, schemaId, json: raw };
}

function renderFile() {
  const files = readdirSync(schemaDir)
    .filter((f) => f.endsWith(".json") && READ_SURFACE_FILES.has(f))
    .sort();
  const missing = [...READ_SURFACE_FILES].filter((f) => !files.includes(f));
  if (missing.length > 0) {
    throw new Error(`missing in-20 schema files: ${missing.join(", ")}`);
  }
  const entries = files.map((file) => readEntry(file));

  const header = [
    "// @generated by scripts/gen-integration-schema-bundle.mjs — DO NOT EDIT BY HAND.",
    "//",
    "// in-21 — the in-20 read-surface JSON-Schema catalog, bundled for the",
    "// Integration Control Center's download endpoint. Source of truth:",
    "// contracts/json/integrations/*.json (the drift-gated artifacts the",
    "// orchestrator emits via scripts/contract-schema-export.mjs from its Zod",
    "// contracts in routes/integrations/contract.ts). Regenerate with",
    "// `corepack pnpm run codegen:integration-schema-bundle`; the",
    "// `check:integration-schema-bundle-drift` gate fails if this file diverges",
    "// from the committed JSON.",
    "",
    "export interface IntegrationReadSchemaCatalogEntry {",
    "  readonly name: string;",
    "  readonly schemaId: string;",
    "  readonly json: string;",
    "}",
    "",
    'export const INTEGRATION_READ_SCHEMA_CATALOG_VERSION = "v1" as const;',
    "",
    "export const integrationReadSchemaCatalog: readonly IntegrationReadSchemaCatalogEntry[] = [",
  ];
  const lines = entries.map((entry) => {
    const name = entry.file.replace(/\.json$/u, "");
    // Use JSON.stringify twice: once to embed the raw JSON string as a TS
    // string literal (preserving the exact bytes from the source file).
    const embedded = JSON.stringify(entry.json);
    return [
      "  {",
      `    name: ${JSON.stringify(name)},`,
      `    schemaId: ${JSON.stringify(entry.schemaId)},`,
      `    json: ${embedded},`,
      "  },",
    ].join("\n");
  });
  const footer = ["];", ""];
  return [...header, ...lines, ...footer].join("\n");
}

function readCurrent() {
  try {
    return readFileSync(outFile, "utf8");
  } catch {
    // missing file → treat as no current content
  }
}

// Run the rendered source through oxfmt (the project's formatter, configured
// by .oxfmtrc.json) so the committed file is format-clean on every regen —
// otherwise `format:check` would reformat it and reintroduce drift against
// the codegen output. Mirrors scripts/gen-dashboard-types.mjs exactly.
function renderFormatted() {
  const raw = renderFile();
  const result = spawnSync("oxfmt", ["--stdin-filepath", outFile], { input: raw, encoding: "utf8" });
  if (result.status !== 0) {
    throw new Error(`oxfmt failed to format generated bundle: ${result.stderr || result.error}`);
  }
  return result.stdout;
}

function main() {
  const check = new Set(argv.slice(2)).has("--check");
  const expected = renderFormatted();
  const current = readCurrent();
  if (current === expected) {
    if (!check) {
      process.stdout.write(`integration schema bundle up to date (${outFileRel}).\n`);
    }
    return;
  }
  if (check) {
    process.stderr.write(
      `integration schema bundle drift detected: ${outFileRel} differs from ` +
        "the committed JSON-Schema files under contracts/json/integrations/.\n" +
        "Regenerate with `corepack pnpm run codegen:integration-schema-bundle` and commit.\n",
    );
    exit(1);
  }
  writeFileSync(outFile, expected);
  process.stdout.write(`updated: ${outFileRel}\n`);
}

if (process.argv[1] === import.meta.filename) {
  main();
}
